'use strict';

// A DECOY declared BEFORE the real export: a named function nothing
// exports, sitting exactly where a "first function in the file" or a bare
// same-file name search would land.
function dangerousOp(input) {
  return 'decoy:' + input;
}

// The real vulnerable implementation. It is ANONYMOUS -- there is no name
// anywhere to match on, so the only thing that can identify it is its own
// position in this file.
module.exports = function (input) {
  return 'danger:' + input + String(dangerousOp).length;
};
